13	#include "orc-rt/Session.h"
14	#include "orc-rt-c/Session.h"
15	
16	namespace orc_rt {
17	
18	class Session::NotificationService : public Service {
19	public:
20	  void addOnDetach(Session::OnDetachFn OnDetach) {
21	    ToNotifyOnDetach.push_back(std::move(OnDetach));
22	  }
23	
24	  void addOnShutdown(Session::OnShutdownFn OnShutdown) {
25	    ToNotifyOnShutdown.push_back(std::move(OnShutdown));
26	  }
27	
28	  void onDetach(OnCompleteFn OnComplete, bool ShutdownRequested) override {
29	    while (!ToNotifyOnDetach.empty()) {
30	      auto ToNotify = std::move(ToNotifyOnDetach.back());
31	      ToNotifyOnDetach.pop_back();
32	      ToNotify();
33	    }
34	    OnComplete();
35	  }
36	
37	  void onShutdown(OnCompleteFn OnComplete) override {
38	    while (!ToNotifyOnShutdown.empty()) {
39	      auto ToNotify = std::move(ToNotifyOnShutdown.back());
40	      ToNotifyOnShutdown.pop_back();
41	      ToNotify();
42	    }
43	    OnComplete();
44	  }
45	
46	private:
47	  std::vector<Session::OnDetachFn> ToNotifyOnDetach;
48	  std::vector<Session::OnShutdownFn> ToNotifyOnShutdown;
49	};
