318	/// Build a PostFn for MockControllerAccess that pushes its work onto the
319	/// supplied queue. With this, a single QueueingRunner::runFIFOUntilEmpty(Q)
320	/// call advances both Session-side and controller-side work.
321	inline MockControllerAccess::PostFn postOnto(QueueingRunner<>::WorkQueue &Q) {
322	  return
323	      [&Q](move_only_function<void()> Work) { Q.push_back(std::move(Work)); };
324	}
