466	TEST(SessionTest, ActiveManagedCallsDelayShutdown) {
467	  QueueingRunner<>::WorkQueue Tasks;
468	  Session S(mockExecutorProcessInfo(), QueueingRunner(Tasks), noErrors);
469	
470	  size_t OpIdx = 0;
471	  std::optional<size_t> DetachOpIdx;
472	  std::optional<size_t> ShutdownOpIdx;
473	  S.createService<MockService>(DetachOpIdx, ShutdownOpIdx, OpIdx);
474	
475	  ASSERT_FALSE(DetachOpIdx);
476	  ASSERT_FALSE(ShutdownOpIdx);
477	
478	  // Take a managed code call token. This should succeed.
479	  auto Tok = TaskGroup::Token(S.managedCodeTokenSource());
480	  ASSERT_TRUE(Tok);
481	
482	  // We expect shutdown to wait for any active managed calls to complete.
483	  bool ShutdownComplete = false;
484	  S.shutdown([&]() { ShutdownComplete = true; });
485	
486	  // Detach should have happened, but shutdown should be waiting on token.
487	  EXPECT_EQ(DetachOpIdx, 0U);
488	  EXPECT_FALSE(ShutdownOpIdx);
489	  EXPECT_FALSE(ShutdownComplete);
490	
491	  // The managed calls code group should have been closed. Assert that we
492	  // can't get a new token.
493	  ASSERT_FALSE(TaskGroup::Token(S.managedCodeTokenSource()));
494	
495	  Tok = TaskGroup::Token(); // Reset token.
496	
497	  EXPECT_EQ(ShutdownOpIdx, 1U);
498	
499	  EXPECT_TRUE(ShutdownComplete);
500	}
